# frozen_string_literal: true

require_relative "test_helper"
require "tmpdir"
require "json"
require "fileutils"

module Tart
  # Golden parity tests: the fixtures in test/fixtures/edit_golden.json were
  # generated by running pi's REAL tool code (read.ts/write.ts/edit.ts/
  # edit-diff.ts/truncate.ts, copied verbatim from the read-only oracle repo)
  # under node --experimental-strip-types — see generate_goldens.mjs for the
  # scenario list and inputs. The port must reproduce them exactly; they are
  # never derived from the port's own behavior.
  #
  # Trailing-whitespace cases are the §5 verbatim-parity point: trailing WS
  # round-trips byte-for-byte — no normalization at any write boundary.
  class GoldenParityTest < Test
    GOLDENS = JSON.parse(File.read(File.expand_path("fixtures/edit_golden.json", __dir__)))

    def setup
      @dir = Dir.mktmpdir("tart-golden-")
    end

    def teardown
      FileUtils.rm_rf(@dir)
    end

    # ---- read: pi's read.ts text path, byte-for-byte ----

    READ_INPUTS = {
      "trailing_ws" => "line one  \nline two\t\n",
      "bom_crlf" => "\uFEFFa\r\nb\r\n",
      "many_lines" => -> { Array.new(2500) { |i| "l#{i + 1}" }.join("\n") + "\n" },
      "byte_limit" => -> { Array.new(100) { |i| "x" * 2000 + "-#{i}" }.join("\n") + "\n" },
    }.freeze

    READ_CASES = {
      "trailing_ws" => ["trailing_ws", {}],
      "bom_crlf" => ["bom_crlf", {}],
      "offset_limit" => ["trailing_ws", {offset: 2, limit: 1}],
      "many_lines" => ["many_lines", {}],
      "byte_limit" => ["byte_limit", {}],
    }.freeze

    def test_read_goldens
      each_golden_case(GOLDENS["read_cases"], READ_CASES) do |name, source, args|
        path = File.join(@dir, "#{source}.txt")
        input = READ_INPUTS.fetch(source)
        File.binwrite(path, input.is_a?(Proc) ? input.call : input)
        Tools::Read.new(cwd: @dir).execute(path:, **args)
      end
    end

    def test_read_error_goldens
      # Constructed error messages are pi-verbatim.
      each_golden_case(GOLDENS["read_cases"], {"offset_beyond_eof" => ""}, errors_only: true) do |name|
        path = File.join(@dir, "#{name}.txt")
        File.write(path, "line one  \nline two\t\n")
        Tools::Read.new(cwd: @dir).execute(path:, offset: 99)
      end
    end

    def test_read_missing_file_is_an_error_result
      # Runtime OS-error strings are runtime-native (Node vs Ruby); the port
      # preserves pi's SHAPE — the failure comes back as an error result
      # naming the path (recorded parity deviation).
      result = Tools::Read.new(cwd: @dir).execute(path: "nope.txt")
      assert result.key?(:error)
      assert_includes result[:error], "nope.txt"
    end

    # ---- write: verbatim bytes in, verbatim bytes out ----

    def test_write_golden_trailing_whitespace_round_trips
      test_case = GOLDENS["write_cases"].find { |c| c["name"] == "verbatim_trailing_ws" }
      content = "no trailing newline  \nsecond\t\n"

      result = Tools::Write.new(cwd: @dir).execute(path: "out1.txt", content:)

      assert_equal test_case["value"]["message"], result
      assert_equal test_case["value"]["written_base64"], [File.binread(File.join(@dir, "out1.txt"))].pack("m0"),
        "write must be byte-verbatim (no newline/whitespace fixup)"
    end

    def test_write_golden_creates_parent_directories
      test_case = GOLDENS["write_cases"].find { |c| c["name"] == "nested_dirs" }
      result = Tools::Write.new(cwd: @dir).execute(path: "deep/nested/dir/out.txt", content: "x")
      assert_equal test_case["value"]["message"], result
      assert test_case["value"]["exists"]
      assert File.exist?(File.join(@dir, "deep/nested/dir/out.txt"))
    end

    # ---- edit: pi's fuzzy matcher end-to-end (message + written bytes) ----

    EDIT_INPUTS = {
      "exact" => "alpha\nbeta\ngamma\n",
      "exact_trailing_ws" => "alpha  \nbeta\t\n",
      "fuzzy_trailing_ws" => "alpha  \nbeta\t\ngamma \n",
      "replacement_trailing_ws" => "alpha\nbeta\n",
      "smart_quotes" => "don\u2019t stop\u2026\n",
      "dashes" => "a\u2013b\u2014c\n",
      "crlf" => "a\r\nb\r\nc\r\n",
      "bom" => "\uFEFFa\nb\n",
      "multi" => "one\ntwo\nthree\nfour\n",
      "multi_fuzzy" => "x  \ny\nz\t\n",
      "not_found" => "a\nb\n",
      "duplicate" => "dup\ndup\n",
      "no_change" => "a\nb\n",
      "empty_old_text" => "a\nb\n",
      "overlap" => "abcd\n",
    }.freeze

    EDIT_EDITS = {
      "exact" => [{old_text: "beta", new_text: "BETA"}],
      "exact_trailing_ws" => [{old_text: "alpha  \nbeta\t\n", new_text: "alpha\n"}],
      "fuzzy_trailing_ws" => [{old_text: "alpha\n", new_text: "ALPHA\n"}],
      "replacement_trailing_ws" => [{old_text: "beta", new_text: "beta  "}],
      "smart_quotes" => [{old_text: "don't stop...", new_text: "done"}],
      "dashes" => [{old_text: "a-b-c", new_text: "abc"}],
      "crlf" => [{old_text: "b", new_text: "B"}],
      "bom" => [{old_text: "a", new_text: "A"}],
      "multi" => [{old_text: "one", new_text: "ONE"}, {old_text: "four", new_text: "FOUR"}],
      "multi_fuzzy" => [{old_text: "x\n", new_text: "X\n"}, {old_text: "z\n", new_text: "Z\n"}],
      "not_found" => [{old_text: "nope", new_text: "x"}],
      "duplicate" => [{old_text: "dup", new_text: "x"}],
      "no_change" => [{old_text: "a", new_text: "a"}],
      "empty_old_text" => [{old_text: "", new_text: "x"}],
      "overlap" => [{old_text: "ab", new_text: "X"}, {old_text: "bc", new_text: "Y"}],
    }.freeze

    def test_edit_goldens_written_bytes_and_message
      GOLDENS["edit_cases"].each do |test_case|
        next unless test_case["ok"] && EDIT_INPUTS.key?(test_case["name"])

        name = test_case["name"]
        # The path-as-given is relative and the cwd supplies the base, like
        # the generator's calls — pi's messages embed the given path.
        relative_path = "e-#{name}.txt"
        File.binwrite(File.join(@dir, relative_path), EDIT_INPUTS.fetch(name))
        tool = Tools::Edit.new(cwd: @dir)
        result = tool.execute(path: relative_path, edits: EDIT_EDITS.fetch(name))
        golden = test_case["value"]

        assert_equal golden["message"], result,
          "edit golden '#{name}': success message must match pi"
        assert_equal golden["written_base64"], [File.binread(File.join(@dir, relative_path))].pack("m0"),
          "edit golden '#{name}': written file bytes must match pi exactly (§5 verbatim parity)"
        next unless golden["details"]

        assert_equal golden["details"]["diff"], tool.details[:diff],
          "edit golden '#{name}': display diff must match pi's generateDiffString"
        assert_equal golden["details"]["firstChangedLine"], tool.details[:first_changed_line]
      end
    end

    def test_edit_error_goldens
      errors = GOLDENS["edit_cases"].reject { |c| c["ok"] }
      errors.each do |test_case|
        name = test_case["name"]
        relative_path = "e-#{name}.txt"
        File.binwrite(File.join(@dir, relative_path), EDIT_INPUTS[name] || "a\nb\n")

        # legacy_top_level_args reproduces the generator's call: execute with
        # an empty edits array (pi's execute validates before the agent-loop
        # prepareArguments hook would fill it).
        edits = name == "legacy_top_level_args" ? [] : EDIT_EDITS.fetch(name, [{old_text: "x", new_text: "y"}])
        result = Tools::Edit.new(cwd: @dir).execute(path: relative_path, edits:)
        assert_equal test_case["error"], error_message_from(result),
          "edit error golden '#{name}' must match pi"
      end
    end

    def test_edit_normalizes_legacy_and_json_argument_shapes
      # pi's prepareEditArguments shapes, exercised through the model-call
      # boundary (Tool#call), like the agent loop's.
      tool = Tools::Edit.new(cwd: @dir)

      path = File.join(@dir, "legacy.txt")
      File.write(path, "hello\nworld\n")
      result = tool.call(path:, edits: [], oldText: "hello", newText: "HELLO")
      assert_equal "Successfully replaced 1 block(s) in #{path}.", result

      path = File.join(@dir, "json.txt")
      File.write(path, "hello\nworld\n")
      result = tool.call(path:, edits: "[{\"oldText\":\"hello\",\"newText\":\"HELLO\"}]")
      assert_equal "Successfully replaced 1 block(s) in #{path}.", result

      path = File.join(@dir, "single.txt")
      File.write(path, "hello\nworld\n")
      result = tool.call(path:, edits: {"oldText" => "hello", "newText" => "HELLO"})
      assert_equal "Successfully replaced 1 block(s) in #{path}.", result
    end

    # ---- edit-diff units ----

    EDIT_UNIT_CALLS = {
      "normalize_smart_quotes" => -> { Tools::EditDiff.normalize_for_fuzzy_match("\u2018x\u2019 \u201Cy\u201D") },
      "normalize_spaces" => -> { Tools::EditDiff.normalize_for_fuzzy_match("a\u00A0b\u2003c\u202Fd") },
      "normalize_dashes" => -> { Tools::EditDiff.normalize_for_fuzzy_match("a\u2010b\u2013c\u2014d\u2212e") },
      "normalize_trailing_ws" => -> { Tools::EditDiff.normalize_for_fuzzy_match("a  \nb\t\nc") },
      "normalize_not_internal_runs" => -> { Tools::EditDiff.normalize_for_fuzzy_match("a  b") },
      "fuzzy_find_exact" => -> { Tools::EditDiff.fuzzy_find_text("abc\n", "abc") },
      "fuzzy_find_fuzzy" => -> { Tools::EditDiff.fuzzy_find_text("abc  \n", "abc") },
      "fuzzy_find_miss" => -> { Tools::EditDiff.fuzzy_find_text("abc\n", "xyz") },
      "detect_line_ending_crlf" => -> { Tools::EditDiff.detect_line_ending("a\r\nb\n") },
      "detect_line_ending_lf" => -> { Tools::EditDiff.detect_line_ending("a\nb\r\n") },
      "detect_line_ending_none" => -> { Tools::EditDiff.detect_line_ending("ab") },
      "split_bom" => -> { JSON.parse(JSON.generate(Tools::EditDiff.split_bom("\uFEFFab"))) },
    }.freeze

    def test_edit_unit_goldens
      each_golden_unit(GOLDENS["edit_unit_cases"], EDIT_UNIT_CALLS)
    end

    # ---- truncate units ----

    TRUNCATE_CALLS = {
      "head_no_truncation" => -> { Tools::Truncate.truncate_head("a\nb\nc") },
      "head_line_limit" => -> { Tools::Truncate.truncate_head(Array.new(30) { |i| "l#{i}" }.join("\n"), max_lines: 10) },
      "head_byte_limit" => -> { Tools::Truncate.truncate_head(Array.new(10) { "y" * 10 }.join("\n"), max_bytes: 25) },
      "head_first_line_exceeds" => -> { Tools::Truncate.truncate_head("z" * 100 + "\nshort\n", max_bytes: 50) },
      "head_trailing_ws_lines" => -> { Tools::Truncate.truncate_head("a  \nb\t\n  c\n", max_lines: 2) },
      "tail_no_truncation" => -> { Tools::Truncate.truncate_tail("a\nb\nc") },
      "tail_line_limit" => -> { Tools::Truncate.truncate_tail(Array.new(30) { |i| "l#{i}" }.join("\n"), max_lines: 10) },
      "tail_byte_limit" => -> { Tools::Truncate.truncate_tail(Array.new(10) { "y" * 10 }.join("\n"), max_bytes: 25) },
      "tail_single_huge_line_partial" => -> { Tools::Truncate.truncate_tail("s" * 100 + "\ntail\n", max_bytes: 30) },
      "format_size" => -> { [Tools::Truncate.format_size(500), Tools::Truncate.format_size(5000),
                             Tools::Truncate.format_size(5_000_000)].join(",") },
      "truncate_line" => -> { Tools::Truncate.truncate_line("a" * 600) },
      "truncate_middle" => -> { Tools::Truncate.truncate_middle("m" * 1000, 100)[:content] },
    }.freeze

    def test_truncate_goldens
      each_golden_unit(GOLDENS["truncate_cases"], TRUNCATE_CALLS)
    end

    private

    # Runs each named golden case: yields the case name, gets the port's
    # output back, and compares with pi's recorded value (camelCase
    # normalized both ways). Errors compare against the recorded message.
    def each_golden_unit(cases, calls)
      cases.each do |test_case|
        call = calls.fetch(test_case["name"])
        if test_case["ok"]
          assert_equal fixture_value(test_case["value"]), port_value(call.call),
            "golden unit '#{test_case['name']}' must match pi"
        else
          error = assert_raises(StandardError) { call.call }
          assert_equal test_case["error"], error.message
        end
      end
    end

    def each_golden_case(cases, inputs, errors_only: false)
      cases.each do |test_case|
        name = test_case["name"]
        next if errors_only == test_case["ok"]
        next unless inputs.key?(name)

        if test_case["ok"]
          actual = unwrap(yield(name, *inputs[name]))
          expected = unwrap(test_case["value"])
          if name == "byte_limit"
            # The generator recorded only a 400-char prefix of this large
            # output; the port must match that prefix and the continuation
            # notice.
            assert_equal expected, actual.to_s[0, expected.length]
            assert_includes actual, "[Showing lines"
          else
            assert_equal expected, actual, "golden '#{name}' must match pi byte-for-byte"
          end
        else
          assert_equal test_case["error"], error_message_from(yield(name, *inputs[name])),
            "golden error '#{name}' must match pi"
        end
      end
    end

    # Tools report constructed errors as {error:} results (the tool
    # contract); raised exceptions pass their message through.
    def error_message_from(result)
      return result[:error] if result.is_a?(Hash) && result.key?(:error)

      result
    end

    # The fixture values are pi's raw results (JSON.stringify of content
    # arrays, base64 written bytes, plain text, or stringified JSON of
    # unit results).
    def unwrap(value)
      value.is_a?(Hash) && value.key?("content") && value["content"].is_a?(Array) ? value["content"][0]["text"] : value
    end

    # Fixture-side normalization: repeatedly-parse stringified JSON into a
    # parsed value (the generator stringifies twice in one case).
    def fixture_value(value)
      case value
      when String
        while value.is_a?(String) && (value.start_with?("{") || value.start_with?("\""))
          value = JSON.parse(value)
        end
        value
      when Hash then value.to_h { |k, v| [k, fixture_value(v)] }
      when Array then value.map { |v| fixture_value(v) }
      else value
      end
    end

    # Port-side normalization: symbol keys to fixture camelCase.
    def port_value(value)
      case value
      when Hash
        value.to_h { |k, v| [k.to_s.gsub(/_([a-z])/) { Regexp.last_match(1).upcase }, port_value(v)] }
      when Array then value.map { |v| port_value(v) }
      when Struct then port_value(value.to_h)
      else value
      end
    end
  end
end
